SELECT 'S1 mentions' AS k, o.id, o.identifier, o.name, o.name_norm, (SELECT count(*) FROM organization_mentions m WHERE m.organization_id=o.id) AS own FROM organizations o WHERE o.id IN (30914707, 1291257)
